function mostCoins(nums: number[]): number {
  const go = (row: number[]): number => {
    let best = 0;
    for (let i = 0; i < row.length; i++) {
      const left = i > 0 ? row[i - 1] : 1, right = i + 1 < row.length ? row[i + 1] : 1;
      best = Math.max(best, left * row[i] * right + go([...row.slice(0, i), ...row.slice(i + 1)]));
    }
    return best;
  };
  return go(nums);
}

