function mostCoins(nums: number[]): number {
  const v = [1, ...nums, 1], n = v.length;
  const memo: number[][] = Array.from({ length: n }, () => new Array(n).fill(-1));
  const best = (i: number, j: number): number => {
    if (j - i < 2) return 0; // nothing between the walls
    if (memo[i][j] >= 0) return memo[i][j];
    let top = 0;
    for (let k = i + 1; k < j; k++) top = Math.max(top, best(i, k) + v[i] * v[k] * v[j] + best(k, j));
    return (memo[i][j] = top);
  };
  return best(0, n - 1);
}

