function mostCoins(nums: number[]): number {
  const v = [1, ...nums, 1], n = v.length;
  const dp: number[][] = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let gap = 2; gap < n; gap++)
    for (let i = 0; i + gap < n; i++) {
      const j = i + gap, walls = v[i] * v[j];
      let top = 0;
      for (let k = i + 1; k < j; k++) top = Math.max(top, dp[i][k] + walls * v[k] + dp[k][j]); // k popped last
      dp[i][j] = top;
    }
  return dp[0][n - 1];
}

